def transform(grid):
    h, w = len(grid), len(grid[0])
    # The repeated background tiles are separated by regularly spaced grid lines.
    # Read the encoded values at the intersections of the internal grid lines;
    # ordinary separator color maps to the tile's fill color.
    rows = [r for r in range(h) if all(v == grid[r][0] for v in grid[r])]
    cols = [c for c in range(w) if all(grid[r][c] == grid[0][c] for r in range(h))]
    if len(rows) < 2 or len(cols) < 2:
        return grid
    out = []
    for ri in range(1, len(rows)):
        row = []
        for ci in range(1, len(cols)):
            v = grid[rows[ri]][cols[ci]]
            row.append(0 if v == 2 else v)
        out.append(row)
    return out
